1	import { randomUUID } from "node:crypto";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { afterAll, beforeAll, describe, expect, it } from "vitest";
4	import { adminClient, anonClient, userClient } from "../helpers/clients";
5	import { closePool, sql } from "../helpers/db";
6	import { createFixtureOrg, type FixtureOrg } from "../helpers/fixtures";
7	
8	// R44 / R20 Storage: bucket payment-slips through the Storage API with the publishable key + user
9	// JWTs. Every object this file creates is tracked and removed in afterAll with the secret key;
10	// object existence is always double-checked in storage.objects with pg.
11	
12	const BUCKET = "payment-slips";
13	// 1x1 transparent PNG.
14	const PNG = Buffer.from(
15	  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
16	  "base64",
17	);
18	const PDF = Buffer.from("%PDF-1.4\n1 0 obj<<>>endobj\ntrailer<<>>\n%%EOF\n");
19	const LEASE = { startDate: "2026-01-01", endDate: "2026-06-30", monthlyRentSen: 100000, depositSen: 0 };
20	
21	let A: FixtureOrg;
22	let B: FixtureOrg;
23	let staffPath: string; // uploaded by A.staff into org A's folder
24	let managerPath: string;
25	let bPath: string; // uploaded by B.staff into org B's folder
26	const created = new Set<string>();
27	
28	const store = (c: SupabaseClient) => c.storage.from(BUCKET);
29	const slipPath = (org: FixtureOrg, ext = "png") => `${org.orgId}/${org.lease!.id}/${randomUUID()}.${ext}`;
30	
31	async function objectExists(name: string): Promise<boolean> {
32	  const rows = await sql("select 1 from storage.objects where bucket_id = $1 and name = $2", [BUCKET, name]);
33	  return rows.length === 1;
34	}
35	
36	async function objectsUnder(prefix: string): Promise<string[]> {
37	  const rows = await sql<{ name: string }>("select name from storage.objects where bucket_id = $1 and name like $2", [
38	    BUCKET,
39	    `${prefix}%`,
40	  ]);
41	  return rows.map((r) => r.name);
42	}
43	
44	async function upload(c: SupabaseClient, path: string, body: Buffer = PNG, contentType = "image/png", upsert = false) {
45	  created.add(path);
46	  return store(c).upload(path, body, { contentType, upsert });
47	}
48	
49	beforeAll(async () => {
50	  [A, B] = await Promise.all([createFixtureOrg({ lease: LEASE }), createFixtureOrg({ lease: LEASE })]);
51	  staffPath = slipPath(A);
52	  managerPath = slipPath(A, "pdf");
53	  bPath = slipPath(B);
54	});
55	
56	afterAll(async () => {
57	  const names = [...created];
58	  // Also sweep anything a traversal probe may have produced under either fixture org.
59	  for (const org of [A, B]) if (org) names.push(...(await objectsUnder(`${org.orgId}/`)));
60	  if (names.length) await store(adminClient()).remove([...new Set(names)]);
61	  await closePool();
62	});
63	
64	describe("R44 R20 storage upload: only staff/manager of the org, into their own org folder", () => {
65	  it("staff uploads a small PNG to <own_org_id>/<lease_id>/<uuid>.png", async () => {
66	    const { error } = await upload(userClient(A.tokens.staff), staffPath);
67	    expect(error).toBeNull();
68	    expect(await objectExists(staffPath)).toBe(true);
69	  });
70	
71	  it("manager uploads a PDF to their own org folder", async () => {
72	    const { error } = await upload(userClient(A.tokens.manager), managerPath, PDF, "application/pdf");
73	    expect(error).toBeNull();
74	    expect(await objectExists(managerPath)).toBe(true);
75	  });
76	
77	  it("staff of org B uploads into org B (setup for cross-org reads)", async () => {
78	    const { error } = await upload(userClient(B.tokens.staff), bPath);
79	    expect(error).toBeNull();
80	  });
81	
82	  for (const who of ["tenantA", "tenantB", "anon"] as const) {
83	    it(`${who} cannot upload into org A's folder`, async () => {
84	      const c = who === "anon" ? anonClient() : userClient(A.tokens[who]);
85	      const p = slipPath(A);
86	      const { error } = await upload(c, p);
87	      expect(error).not.toBeNull();
88	      expect(await objectExists(p)).toBe(false);
89	    });
90	  }
91	
92	  for (const who of ["staff", "manager"] as const) {
93	    it(`org B ${who} cannot upload into org A's folder`, async () => {
94	      const p = slipPath(A);
95	      const { error } = await upload(userClient(B.tokens[who]), p);
96	      expect(error).not.toBeNull();
97	      expect(await objectExists(p)).toBe(false);
98	    });
99	  }
100	
101	  it("staff cannot upload outside an org folder: bucket root, random uuid folder, non-uuid folder", async () => {
102	    for (const p of [`${randomUUID()}.png`, `${randomUUID()}/${randomUUID()}.png`, `not-an-org/${randomUUID()}.png`]) {
103	      const { error } = await upload(userClient(A.tokens.staff), p);
104	      expect({ p, refused: error !== null }).toEqual({ p, refused: true });
105	      expect(await objectExists(p)).toBe(false);
106	    }
107	  });
108	
109	  it("path traversal ('../' and encoded) from own folder into another org's folder is refused or stays inside own folder", async () => {
110	    const target = `${B.orgId}/${randomUUID()}.png`;
111	    const probes = [
112	      `${A.orgId}/../${target}`,
113	      `${A.orgId}/%2e%2e/${target}`,
114	      `${A.orgId}/..%2f${target}`,
115	      `./${A.orgId}/../${target}`,
116	    ];
117	    for (const p of probes) {
118	      const { data, error } = await upload(userClient(A.tokens.staff), p);
119	      if (!error) {
120	        // Accepted only as an opaque key that still starts with A's folder.
121	        expect(data?.path.startsWith(`${A.orgId}/`)).toBe(true);
122	      }
123	    }
124	    expect(await objectsUnder(target)).toEqual([]);
125	    const [b] = await sql<{ n: number }>(
126	      "select count(*)::int as n from storage.objects where bucket_id = $1 and name like $2 and name not in ($3)",
127	      [BUCKET, `${B.orgId}/%`, bPath],
128	    );
129	    expect(b.n).toBe(0);
130	    // And org B's own staff cannot find anything planted at the traversal target.
131	    const { error } = await store(userClient(B.tokens.staff)).download(target);
132	    expect(error).not.toBeNull();
133	  });
134	
135	  it("oversize file (> 5 MiB) is rejected", async () => {
136	    const p = slipPath(A);
137	    const big = Buffer.alloc(5 * 1024 * 1024 + 1, 0);
138	    PNG.copy(big);
139	    const { error } = await upload(userClient(A.tokens.staff), p, big, "image/png");
140	    expect(error).not.toBeNull();
141	    expect(await objectExists(p)).toBe(false);
142	  });
143	
144	  it("wrong MIME types are rejected (text/plain, text/html, image/svg+xml, application/octet-stream)", async () => {
145	    for (const mime of ["text/plain", "text/html", "image/svg+xml", "application/octet-stream"]) {
146	      const p = slipPath(A, "png");
147	      const { error } = await upload(userClient(A.tokens.staff), p, Buffer.from("<script>alert(1)</script>"), mime);
148	      expect({ mime, refused: error !== null }).toEqual({ mime, refused: true });
149	      expect(await objectExists(p)).toBe(false);
150	    }
151	  });
152	
153	  it("staff cannot overwrite (upsert) an existing slip: no UPDATE policy", async () => {
154	    const [before] = await sql<{ j: unknown }>(
155	      "select to_jsonb(o) - 'last_accessed_at' as j from storage.objects o where bucket_id = $1 and name = $2",
156	      [BUCKET, staffPath],
157	    );
158	    const { error } = await upload(userClient(A.tokens.manager), staffPath, PNG, "image/png", true);
159	    expect(error).not.toBeNull();
160	    const [after] = await sql<{ j: unknown }>(
161	      "select to_jsonb(o) - 'last_accessed_at' as j from storage.objects o where bucket_id = $1 and name = $2",
162	      [BUCKET, staffPath],
163	    );
164	    expect(after.j).toEqual(before.j);
165	  });
166	
167	  it("nobody (staff, manager, tenant, other org, anon) can delete or move a slip: no DELETE/UPDATE policy", async () => {
168	    const clients = [
169	      userClient(A.tokens.staff),
170	      userClient(A.tokens.manager),
171	      userClient(A.tokens.tenantA),
172	      userClient(B.tokens.manager),
173	      anonClient(),
174	    ];
175	    for (const c of clients) {
176	      await store(c).remove([staffPath]);
177	      await store(c).move(staffPath, `${A.orgId}/${randomUUID()}.png`);
178	      expect(await objectExists(staffPath)).toBe(true);
179	    }
180	  });
181	});
182	
183	describe("R44 storage read: tenants, other orgs and anon cannot read, list or sign", () => {
184	  it("staff and manager of org A can download and sign their org's slip (positive control)", async () => {
185	    for (const t of [A.tokens.staff, A.tokens.manager]) {
186	      const { data, error } = await store(userClient(t)).download(staffPath);
187	      expect(error).toBeNull();
188	      expect(Buffer.from(await data!.arrayBuffer()).equals(PNG)).toBe(true);
189	    }
190	    const { data, error } = await store(userClient(A.tokens.staff)).createSignedUrl(staffPath, 60);
191	    expect(error).toBeNull();
192	    expect(data?.signedUrl).toBeTruthy();
193	  });
194	
195	  const outsiders = () =>
196	    [
197	      ["anon", anonClient()],
198	      ["tenantA (lease's own tenant)", userClient(A.tokens.tenantA)],
199	      ["tenantB", userClient(A.tokens.tenantB)],
200	      ["org B staff", userClient(B.tokens.staff)],
201	      ["org B manager", userClient(B.tokens.manager)],
202	    ] as const;
203	
204	  it("outsiders cannot download the slip", async () => {
205	    for (const [who, c] of outsiders()) {
206	      const { data, error } = await store(c).download(staffPath);
207	      expect({ who, refused: error !== null && data === null }).toEqual({ who, refused: true });
208	    }
209	  });
210	
211	  it("outsiders cannot create a signed URL for it", async () => {
212	    for (const [who, c] of outsiders()) {
213	      const { data, error } = await store(c).createSignedUrl(staffPath, 60);
214	      expect({ who, refused: error !== null || !data?.signedUrl }).toEqual({ who, refused: true });
215	    }
216	  });
217	
218	  it("outsiders listing org A's folders see nothing", async () => {
219	    for (const [who, c] of outsiders()) {
220	      for (const prefix of [A.orgId, `${A.orgId}/${A.lease!.id}`, ""]) {
221	        const { data } = await store(c).list(prefix);
222	        const names = (data ?? []).map((o) => o.name);
223	        expect({ who, prefix, names: names.filter((n) => staffPath.includes(n) && n.length > 0) }).toEqual({
224	          who,
225	          prefix,
226	          names: [],
227	        });
228	      }
229	    }
230	  });
231	
232	  it("the public URL of the slip does not serve the file (bucket is private)", async () => {
233	    const { data } = store(anonClient()).getPublicUrl(staffPath);
234	    const res = await fetch(data.publicUrl);
235	    expect(res.status).toBeGreaterThanOrEqual(400);
236	    await res.arrayBuffer();
237	  });
238	
239	  it("an authenticated object URL with a tenant token is refused", async () => {
240	    const { data } = store(anonClient()).getPublicUrl(staffPath);
241	    const url = data.publicUrl.replace("/object/public/", "/object/authenticated/");
242	    const res = await fetch(url, { headers: { Authorization: `Bearer ${A.tokens.tenantA}` } });
243	    expect(res.status).toBeGreaterThanOrEqual(400);
244	    await res.arrayBuffer();
245	  });
246	
247	  it("org A staff cannot read org B's slip", async () => {
248	    const { error } = await store(userClient(A.tokens.staff)).download(bPath);
249	    expect(error).not.toBeNull();
250	  });
251	
252	  it("listing buckets as anon/tenant does not reveal payment-slips config to write to", async () => {
253	    // Bucket metadata is not secret, but no client may create or update a bucket.
254	    const { error } = await userClient(A.tokens.manager).storage.createBucket(`evil-${randomUUID().slice(0, 6)}`, { public: true });
255	    expect(error).not.toBeNull();
256	    const { error: e2 } = await userClient(A.tokens.manager).storage.updateBucket(BUCKET, { public: true });
257	    expect(e2).not.toBeNull();
258	    const [b] = await sql<{ public: boolean }>("select public from storage.buckets where id = $1", [BUCKET]);
259	    expect(b.public).toBe(false);
260	  });
261	});
262	
263	describe("R44 R20 slip_path must point to an existing file in its own org's folder (record_payment)", () => {
264	  const rec = (actor: string, leaseId: string, slip: string) =>
265	    sql("select * from private.record_payment($1, $2, 100, 'bank_transfer', now(), $3, null)", [actor, leaseId, slip]);
266	
267	  it("a slip that exists but lives in another org's folder is refused P0400", async () => {
268	    await expect(rec(A.users.staff.userId, A.lease!.id, bPath)).rejects.toMatchObject({ code: "P0400" });
269	  });
270	
271	  it("a path in the own org folder with no uploaded object is refused P0400", async () => {
272	    await expect(rec(A.users.staff.userId, A.lease!.id, slipPath(A))).rejects.toMatchObject({ code: "P0400" });
273	  });
274	
275	  it("a traversal-looking slip path is refused", async () => {
276	    await expect(rec(A.users.staff.userId, A.lease!.id, `${A.orgId}/../${bPath}`)).rejects.toMatchObject({ code: "P0400" });
277	  });
278	});
