1	import { afterAll, describe, expect, it } from "vitest";
2	import { closePool, sql } from "../helpers/db";
3	
4	// Catalog invariants, read as `postgres` from pg_catalog / information_schema. These pin the
5	// R42/R43/R44/R47 guarantees at the DB level, independent of any client: if a later migration
6	// adds a table without RLS, grants anon something, or exposes a function, one of these fails.
7	
8	const TABLES = [
9	  "audit_log",
10	  "gateway_bills",
11	  "invoices",
12	  "leases",
13	  "memberships",
14	  "organizations",
15	  "payment_allocations",
16	  "payments",
17	  "tenants",
18	  "units",
19	];
20	
21	const MONEY_FUNCTIONS = [
22	  "allocate_payment",
23	  "apply_gateway_callback",
24	  "approve_payment",
25	  "create_gateway_bill",
26	  "lock_payment_for_manager",
27	  "record_payment",
28	  "reject_payment",
29	  "void_payment",
30	];
31	
32	// The only functions RLS (and Storage's RLS) needs to call as `authenticated` (SPEC Integration contracts).
33	const RLS_HELPERS = ["can_upload_slip", "is_lease_tenant", "is_org_member", "is_tenant_org"];
34	
35	// Extension member functions (none expected in public today) are not "functions we create".
36	const OWN_FUNCTIONS = `
37	  select p.oid, n.nspname as schema, p.proname as name, p.prosecdef as secdef, p.proconfig as config
38	    from pg_proc p
39	    join pg_namespace n on n.oid = p.pronamespace
40	   where n.nspname = any($1::text[])
41	     and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')`;
42	
43	afterAll(closePool);
44	
45	describe("R42 R47 catalog: RLS enabled on every public table", () => {
46	  it("public holds exactly the 10 contract tables and nothing else (no views, no matviews, no foreign tables)", async () => {
47	    const rows = await sql<{ relname: string; relkind: string }>(
48	      `select c.relname, c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
49	        where n.nspname = 'public' and c.relkind in ('r','p','v','m','f') order by 1`,
50	    );
51	    expect(rows.map((r) => `${r.relname}:${r.relkind}`)).toEqual(TABLES.map((t) => `${t}:r`));
52	  });
53	
54	  it("every public table has relrowsecurity = true", async () => {
55	    const rows = await sql<{ relname: string; rls: boolean }>(
56	      `select c.relname, c.relrowsecurity as rls from pg_class c join pg_namespace n on n.oid = c.relnamespace
57	        where n.nspname = 'public' and c.relkind in ('r','p') order by 1`,
58	    );
59	    expect(rows.filter((r) => !r.rls).map((r) => r.relname)).toEqual([]);
60	    expect(rows.length).toBe(TABLES.length);
61	  });
62	
63	  it("every public view (if any) is security_invoker", async () => {
64	    const rows = await sql<{ relname: string }>(
65	      `select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
66	        where n.nspname = 'public' and c.relkind = 'v'
67	          and not coalesce(c.reloptions @> array['security_invoker=true'] or c.reloptions @> array['security_invoker=on'], false)`,
68	    );
69	    expect(rows).toEqual([]);
70	    const mat = await sql(`select 1 from pg_matviews where schemaname = 'public'`);
71	    expect(mat).toEqual([]); // a matview cannot be security_invoker and has no RLS
72	  });
73	});
74	
75	describe("R42 catalog: anon has zero privileges", () => {
76	  it("no table / column grants to anon in information_schema", async () => {
77	    const t = await sql(
78	      `select table_name, privilege_type from information_schema.role_table_grants
79	        where grantee = 'anon' and table_schema in ('public','private')`,
80	    );
81	    expect(t).toEqual([]);
82	    const c = await sql(
83	      `select table_name, column_name, privilege_type from information_schema.column_privileges
84	        where grantee = 'anon' and table_schema in ('public','private')`,
85	    );
86	    expect(c).toEqual([]);
87	  });
88	
89	  it("has_table_privilege / has_any_column_privilege are false for anon on every public relation (incl. via PUBLIC)", async () => {
90	    const rows = await sql<{ relname: string }>(
91	      `select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
92	        where n.nspname = 'public' and c.relkind in ('r','p','v','m','f')
93	          and (has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
94	               or has_any_column_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,REFERENCES'))`,
95	    );
96	    expect(rows).toEqual([]);
97	  });
98	
99	  it("no sequence in public is usable by anon or authenticated", async () => {
100	    const rows = await sql<{ relname: string; role: string }>(
101	      `select c.relname, r.role from pg_class c join pg_namespace n on n.oid = c.relnamespace
102	        cross join (values ('anon'), ('authenticated')) r(role)
103	        where n.nspname = 'public' and c.relkind = 'S'
104	          and has_sequence_privilege(r.role, c.oid, 'USAGE,SELECT,UPDATE')`,
105	    );
106	    expect(rows).toEqual([]);
107	  });
108	
109	  it("anon can execute no function in public or private and has no USAGE on private", async () => {
110	    const rows = await sql<{ schema: string; name: string }>(
111	      `${OWN_FUNCTIONS} and has_function_privilege('anon', p.oid, 'EXECUTE')`,
112	      [["public", "private"]],
113	    );
114	    expect(rows.map((r) => `${r.schema}.${r.name}`)).toEqual([]);
115	    const [u] = await sql<{ ok: boolean }>(`select has_schema_privilege('anon', 'private', 'USAGE') as ok`);
116	    expect(u.ok).toBe(false);
117	  });
118	
119	  // Scoped to the migration role (postgres): Supabase's own supabase_admin default ACL in public
120	  // still grants anon everything, and postgres cannot change it. That is why the next test pins
121	  // every public/private object to owner postgres, so nothing is created under supabase_admin.
122	  it("default privileges of the migration role (postgres) in public/private grant nothing to anon/authenticated", async () => {
123	    const rows = await sql<{ schema: string; objtype: string; acl: string; grantee: string }>(
124	      `select n.nspname as schema, d.defaclobjtype as objtype, a.privilege_type as acl, a.grantee::regrole::text as grantee
125	         from pg_default_acl d
126	         join pg_namespace n on n.oid = d.defaclnamespace
127	         cross join lateral aclexplode(d.defaclacl) a
128	        where n.nspname in ('public','private') and d.defaclrole = 'postgres'::regrole
129	          and a.grantee in ('anon'::regrole, 'authenticated'::regrole, 0::oid)`,
130	    );
131	    expect(rows).toEqual([]);
132	  });
133	
134	  it("every relation and function in public/private is owned by postgres (never supabase_admin, whose defaults grant anon)", async () => {
135	    const rels = await sql<{ name: string; owner: string }>(
136	      `select c.relname as name, c.relowner::regrole::text as owner from pg_class c join pg_namespace n on n.oid = c.relnamespace
137	        where n.nspname in ('public','private') and c.relowner <> 'postgres'::regrole`,
138	    );
139	    expect(rels).toEqual([]);
140	    const fns = await sql<{ name: string; owner: string }>(
141	      `select p.proname as name, p.proowner::regrole::text as owner from pg_proc p join pg_namespace n on n.oid = p.pronamespace
142	        where n.nspname in ('public','private') and p.proowner <> 'postgres'::regrole`,
143	    );
144	    expect(fns).toEqual([]);
145	  });
146	});
147	
148	describe("R42 catalog: authenticated has only SELECT on the matrix tables + UPDATE(phone) on tenants", () => {
149	  it("table-level grants to authenticated are exactly SELECT on the 10 tables", async () => {
150	    const rows = await sql<{ table_name: string; privilege_type: string }>(
151	      `select table_name, privilege_type from information_schema.role_table_grants
152	        where grantee = 'authenticated' and table_schema = 'public' order by 1, 2`,
153	    );
154	    expect(rows.map((r) => `${r.table_name}:${r.privilege_type}`)).toEqual(TABLES.map((t) => `${t}:SELECT`));
155	  });
156	
157	  it("no INSERT/DELETE/TRUNCATE/TRIGGER/REFERENCES on any public table for authenticated", async () => {
158	    const rows = await sql<{ relname: string }>(
159	      `select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
160	        where n.nspname = 'public' and c.relkind in ('r','p')
161	          and (has_table_privilege('authenticated', c.oid, 'INSERT,DELETE,TRUNCATE,TRIGGER,REFERENCES')
162	               or has_any_column_privilege('authenticated', c.oid, 'INSERT,REFERENCES'))`,
163	    );
164	    expect(rows).toEqual([]);
165	  });
166	
167	  it("UPDATE is granted on exactly one column: tenants.phone", async () => {
168	    const rows = await sql<{ rel: string; col: string }>(
169	      `select c.relname as rel, a.attname as col
170	         from pg_class c join pg_namespace n on n.oid = c.relnamespace
171	         join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
172	        where n.nspname = 'public' and c.relkind in ('r','p')
173	          and has_column_privilege('authenticated', c.oid, a.attnum, 'UPDATE')
174	        order by 1, 2`,
175	    );
176	    expect(rows.map((r) => `${r.rel}.${r.col}`)).toEqual(["tenants.phone"]);
177	  });
178	
